using Image=UnityEngine.UI.Image;using UnityEngine.InputSystem.UI;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.UIElements;using Abyss;using Abyss.Story;
public sealed class VoyageMobileControls:VoyageUI {
 RectTransform safe;GameObject stick,fishBoost,shipBoost,interact,pause;FishPilot pilot;ShipController ship;UnderwaterDayStory story;ShipVisitDialogue dialogue;UnityEngine.UI.Text actionLabel;
 protected override void Awake(){base.Awake();root.GetComponent<Canvas>().sortingOrder=6500;var scaler=root.GetComponent<CanvasScaler>();scaler.referenceResolution=new Vector2(1280,720);scaler.screenMatchMode=CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;scaler.matchWidthOrHeight=1;VoyageTouchInput.Reset();}
 void Start(){if(!VoyageTouchInput.Enabled){gameObject.SetActive(false);return;}var module=EventSystem.current.GetComponent<InputSystemUIInputModule>();if(!module)module=EventSystem.current.gameObject.AddComponent<InputSystemUIInputModule>();module.AssignDefaultActions();module.pointerBehavior=UIPointerBehavior.SingleMouseOrPenButMultiTouchAndTrack;safe=safeArea?safeArea:VoyageSafeArea.Create(root);pilot=FindFirstObjectByType<FishPilot>();ship=FindFirstObjectByType<ShipController>();story=FindFirstObjectByType<UnderwaterDayStory>();dialogue=FindFirstObjectByType<ShipVisitDialogue>();
 var zone=Rect("Movement joystick",safe,new Vector2(0,0),Vector2.zero);zone.anchorMin=Vector2.zero;zone.anchorMax=new Vector2(.43f,.55f);zone.pivot=Vector2.zero;zone.offsetMin=zone.offsetMax=Vector2.zero;var touchArea=zone.gameObject.AddComponent<Image>();touchArea.color=Color.clear;stick=zone.gameObject;
 var baseImage=Icon("Floating joystick base",zone,new Vector2(170,205),new Vector2(240,240),"mobile_stick_base",Vector2.zero);baseImage.raycastTarget=false;var knob=Icon("Joystick knob",baseImage.transform,Vector2.zero,new Vector2(86,86),"mobile_stick_knob",Vector2.one*.5f);knob.raycastTarget=false;var joystick=stick.AddComponent<VoyageJoystick>();joystick.knob=knob.rectTransform;joystick.visual=baseImage.rectTransform;gameObject.AddComponent<VoyageScreenDialogueTap>();
 fishBoost=Boost("Fish boost","mobile_fish_boost",true);shipBoost=Boost("Ship boost","mobile_ship_boost",false);
 var action=Icon("Interact or continue",safe,new Vector2(-105,195),new Vector2(108,108),"mobile_interact",new Vector2(1,0));interact=action.gameObject;interact.AddComponent<UnityEngine.UI.Button>().onClick.AddListener(Interact);actionLabel=Label("Interaction caption",interact.transform,new Vector2(0,-69),new Vector2(180,36),"Konuş",22);
 var pauseImage=Icon("Mobile pause",safe,new Vector2(-52,-52),new Vector2(64,64),"mobile_blank",Vector2.one);pause=pauseImage.gameObject;Label("Pause symbol",pause.transform,Vector2.zero,new Vector2(48,48),"II",29);pause.AddComponent<UnityEngine.UI.Button>().onClick.AddListener(()=>{VoyageTouchInput.Reset();var menu=FindFirstObjectByType<VoyagePauseMenu>();if(VoyagePauseMenu.IsOpen)menu.Close();else menu.Open();});
 AdaptHud();}
 Image Icon(string name,Transform parent,Vector2 at,Vector2 size,string sprite,Vector2 anchor){var image=Picture(name,parent,at,size,sprite);image.preserveAspect=true;image.rectTransform.anchorMin=image.rectTransform.anchorMax=anchor;return image;}
 GameObject Boost(string name,string art,bool fish){var image=Icon(name,safe,new Vector2(-105,195),new Vector2(116,116),art,new Vector2(1,0));var button=image.gameObject.AddComponent<VoyageBoostButton>();button.fish=fish;button.ship=ship;return image.gameObject;}
 void AdaptHud(){if(!ship)return;ship.gameObject.AddComponent<VoyageCardTouch>();var view=FindFirstObjectByType<OrbRewardToggleView>();if(view){var hint=view.transform.Find("KeyHint");if(hint)hint.gameObject.SetActive(false);var canvas=view.GetComponentInParent<Canvas>();var scaler=canvas.GetComponent<CanvasScaler>();if(scaler)scaler.matchWidthOrHeight=1;if(!canvas.transform.Find("Mobile safe area")){var children=canvas.transform.Cast<Transform>().ToArray();var area=VoyageSafeArea.Create((RectTransform)canvas.transform);foreach(var child in children)child.SetParent(area,false);}var left=view.transform.parent as RectTransform;if(left){left.localScale=Vector3.one*1.25f;}var selector=(RectTransform)view.transform;selector.localScale=Vector3.one*1.35f;selector.anchoredPosition=new Vector2(115,-200);var bar=canvas.GetComponentsInChildren<RectTransform>(true).FirstOrDefault(r=>r.name=="WaterPurificationBar");if(bar&&bar.parent==left)bar.anchoredPosition=new Vector2(bar.anchoredPosition.x,-280);var target=new GameObject("Loot touch target",typeof(RectTransform),typeof(Image));var rect=target.GetComponent<RectTransform>();rect.SetParent(view.transform,false);rect.anchorMin=rect.anchorMax=Vector2.one*.5f;rect.sizeDelta=new Vector2(((RectTransform)view.transform).rect.width,100);target.GetComponent<Image>().color=Color.clear;}
 var ui=ship.uiManager;if(ui&&ui.levelUpDocument&&ui.levelUpDocument.panelSettings){var settings=Instantiate(ui.levelUpDocument.panelSettings);settings.name="Mobile card panel";settings.scaleMode=PanelScaleMode.ScaleWithScreenSize;settings.referenceResolution=new Vector2Int(1280,720);settings.screenMatchMode=PanelScreenMatchMode.MatchWidthOrHeight;settings.match=1;ui.levelUpDocument.panelSettings=settings;}}
 public void Interact(){if(VoyagePauseMenu.IsOpen||StorySceneJourney.Instance.IsTransitioning)return;if(story)story.RequestInteraction();else if(dialogue&&dialogue.UI.Active)dialogue.UI.Advance();}
 bool Nearby(){if(!story)return false;if(story.ui.Active||story.ui.ContinuePromptVisible)return false;var at=(Vector2)pilot.transform.position;var third=story.thirdChapter;if(third&&third.Started)return !third.Complete&&(third.Stage==ThirdChapterStage.Travel||third.Stage==ThirdChapterStage.LeaderReady)&&Vector2.Distance(at,third.leader.Position)<third.talkRadius;var second=story.secondChapter;if(second&&second.Started)return second.Stage==SecondChapterStage.AttendAnnouncement&&Vector2.Distance(at,second.meetingPoint)<second.meetingRadius;if(story.Complete)return story.NearHome;if(story.Stage==UnderwaterDayStage.InspectBodies&&story.bodies.Any(b=>Vector2.Distance(at,b.position)<story.interactDistance))return true;return Vector2.Distance(at,story.mayor.Position)<story.interactDistance;}
 void Update(){if(!stick)return;if(ship&&!dialogue)dialogue=ship.GetComponent<ShipVisitDialogue>();bool blocked=VoyagePauseMenu.IsOpen||StorySceneJourney.Instance.IsTransitioning;bool final=StorySceneJourney.Instance.Stage==JourneyStage.Finale;bool speech=(story&&story.ui.Active)||(dialogue&&dialogue.UI.Active);bool move=!blocked&&!final&&Time.timeScale>0&&(pilot&&!pilot.ControlsLocked||ship&&ship.enabled);stick.SetActive(move);fishBoost.SetActive(move&&pilot);shipBoost.SetActive(move&&ship);bool use=!blocked&&!speech&&story&&story.Stage!=UnderwaterDayStage.InspectBodies&&Nearby();interact.SetActive(use);if(use){actionLabel.text=speech?"Devam":story&&story.Complete&&story.NearHome?"Eve gir":story&&story.Stage==UnderwaterDayStage.InspectBodies?"İncele":"Konuş";interact.GetComponent<RectTransform>().anchoredPosition=new Vector2(-105,350);}
 pause.SetActive(!blocked&&!final);pause.GetComponent<RectTransform>().anchoredPosition=new Vector2(-52,ship?-195:-52);}
 void ResetHeld(){VoyageTouchInput.Reset();foreach(var control in GetComponentsInChildren<VoyageJoystick>(true))control.Cancel();foreach(var control in GetComponentsInChildren<VoyageBoostButton>(true))control.Cancel();}
 void OnDisable(){ResetHeld();}void OnApplicationFocus(bool focus){if(!focus)ResetHeld();}void OnApplicationPause(bool value){if(value){ResetHeld();var menu=FindFirstObjectByType<VoyagePauseMenu>();if(menu&&!VoyagePauseMenu.IsOpen&&StorySceneJourney.Instance.Stage!=JourneyStage.Finale)menu.Open();}}
}

